import common as c
from common import R,P,np
c.check();assert c.read(R/'validation.json')['passed'];z=c.load(R/'OOF.npz');ref=c.load(R/'frozen-reference.npz');y=z['y'];fold=z['fold'];N=len(y);assert N==400
with c.Monitor('score',300):
 a=z['control'];b=z['gamma'];np.testing.assert_array_equal(a,ref['old_first_CNN']);qa=ref['best021']+ref['coefficient']*(a-ref['old_first_CNN']);qb=ref['best021']+ref['coefficient']*(b-ref['old_first_CNN']);np.testing.assert_array_equal(qa,ref['best021']);pred={'control':a,'gamma':b,'fixed_control':qa,'fixed_gamma':qb};rmse=lambda p:float(np.sqrt(np.mean((y-p)**2)));draws=np.random.default_rng(202610214).integers(0,400,size=(10000,400));counts=np.stack([np.bincount(row,minlength=400) for row in draws]);comparisons={};bootout={}
 def compare(name,old,new):
  ae=(y-old)**2;be=(y-new)**2;boots=np.sqrt((counts@ae)/400)-np.sqrt((counts@be)/400);bootout[name]=boots;direct=np.array([np.sqrt(ae[i].mean())-np.sqrt(be[i].mean()) for i in draws[:23]]);assert abs(direct-boots[:23]).max()<1e-12;gain=rmse(old)-rmse(new);ind=(np.linalg.norm(y-old)-np.linalg.norm(y-new))/20;assert abs(ind-gain)<1e-12;delta=ae-be;order=np.argsort(delta,kind='stable');keep=order[:-5];fg=[float(np.sqrt(ae[fold==k].mean())-np.sqrt(be[fold==k].mean())) for k in range(5)];top5gain=float(np.sqrt(ae[keep].mean())-np.sqrt(be[keep].mean()));ci=np.quantile(boots,[.025,.975]).tolist()
  return {'baseline_RMSE':rmse(old),'candidate_RMSE':rmse(new),'gain_baseline_minus_candidate':gain,'fold_gains':fg,'positive_folds':sum(v>0 for v in fg),'conditional_CI95':ci,'top5_removed_gain':top5gain,'top5_removed_IDs':z['ids'][order[-5:]].tolist(),'positive_IDs':int(np.sum(delta>0)),'prediction_delta_RMS':float(np.sqrt(np.mean((new-old)**2)))}
 comparisons['standalone']=compare('standalone',a,b);comparisons['fixed_ensemble']=compare('fixed_ensemble',qa,qb)
 q=comparisons['standalone'];criteria={'technical_validation':True,'gain_at_least_0_02':q['gain_baseline_minus_candidate']>=.02,'at_least3_folds':q['positive_folds']>=3,'conditional_CI_lower_positive':q['conditional_CI95'][0]>0,'top5_removed_positive':q['top5_removed_gain']>0};eligible=all(criteria.values())
 residuals=[{'ID':str(z['ids'][i]),'fold':int(fold[i]),'target':float(y[i]),**{name+'_prediction':float(p[i]) for name,p in pred.items()},**{name+'_residual':float(p[i]-y[i]) for name,p in pred.items()},'standalone_squared_error_gain':float((a[i]-y[i])**2-(b[i]-y[i])**2),'fixed_ensemble_squared_error_gain':float((qa[i]-y[i])**2-(qb[i]-y[i])**2)} for i in range(N)];c.write(R/'ID-residuals.json',residuals)
 c.arrays(R/'ensemble-OOF.npz',ids=z['ids'],y=y,fold=fold,coefficient=ref['coefficient'],**pred);c.arrays(R/'bootstrap.npz',draws=draws,**bootout)
 report={'study':214,'status':'검증 완료; 결과 보고 후 정지','comparisons':comparisons,'criteria':criteria,'further_review_eligible':eligible,'selection_or_promotion':False,'decision':'사전 기준 충족 여부를 보고하고 정지. best021 유지.' if eligible else '사전 기준 미달. 이 고정 감마 변환 분기를 종료하고 best021 유지.','effect_scope':'원본 개발400, 단일seed TinyCNN 감마 변환 대조. 앙상블은 고정 첫seed 출력 치환 진단이며 후단 전체 재학습 아님.','limitations':['같은400의 반복 사용과 누적 선택 편향. 독립 holdout 아님.','한 seed의 조건부 CI이며 seed분산·재학습 불확실성을 포함하지 않음.','구조 검사 통과와 회귀 개선 여부는 타깃 불변성 증명이 아님.','실패는 이번 고정 양방향 gamma 이동 조건에 한정. 모든 증강·물리 특징의 무효가 아님.'],'OOF_SHA256':c.sha(R/'OOF.npz'),'ensemble_OOF_SHA256':c.sha(R/'ensemble-OOF.npz'),'bootstrap_SHA256':c.sha(R/'bootstrap.npz'),'bootstrap_count':10000,'bootstrap_seed':202610214,'gain_sign':'baseline RMSE minus candidate RMSE; positive means improvement','plan_SHA256':c.sha(R/'plan.json'),'validation_SHA256':c.sha(R/'validation.json'),'cost':0,'new_install_download_holdout_test_CSV_submission':False};c.write(R/'summary.json',report);c.emit(report)
